const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southJavaPoint = ee.Geometry.Point([110.2273416, -8.879787]);
  const northJavaPoint = ee.Geometry.Point([109.953683, -5.741852]);
  const analysisDate = '2019-08-04';

  // 2. Data Acquisition & Check
  // Using MODIS-Aqua Level-3 SMI for daily chlorophyll-a concentration.
  let imageCollection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(analysisDate, ee.Date(analysisDate).advance(1, 'day'))
    .select('chlor_a');

  const imageCount = imageCollection.size().getInfo();
  if (imageCount === 0) {
    console.log('No images found for the specified date.');
    console.log('A: No');
    return;
  }

  const image = imageCollection.first();

  // 3. Processing & Calculation
  // Extract chlorophyll-a values at the specified points.
  // The native resolution is ~4km, so a 1000m scale is safe and fast.
  const southChlDict = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southJavaPoint,
    scale: 1000,
    crs: 'EPSG:4326'
  });

  const northChlDict = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northJavaPoint,
    scale: 1000,
    crs: 'EPSG:4326'
  });

  // Fetch the results from the server
  const southChl = southChlDict.get('chlor_a').getInfo();
  const northChl = northChlDict.get('chlor_a').getInfo();

  // 4. Validation & Final Answer
  console.log(`Image count on ${analysisDate}: ${imageCount}`);

  if (southChl === null || northChl === null) {
    console.log(`Southern Java Chl-a: ${southChl === null ? 'No Data (Cloud/Land)' : southChl.toFixed(4)} mg/m^3`);
    console.log(`Northern Java Chl-a: ${northChl === null ? 'No Data (Cloud/Land)' : northChl.toFixed(4)} mg/m^3`);
    console.log('Could not retrieve a valid pixel value for one or both locations.');
    console.log('C2');
    return;
  }

  // Check for unreasonable values, although MODIS L3 is generally well-processed
  if (southChl < 0 || southChl > 100 || northChl < 0 || northChl > 100) {
      console.log(`Southern Java Chl-a: ${southChl.toFixed(4)} mg/m^3`);
      console.log(`Northern Java Chl-a: ${northChl.toFixed(4)} mg/m^3`);
      console.log('Unreasonable chlorophyll value detected.');
      console.log('C3');
      return;
  }

  console.log(`Southern Java Chl-a: ${southChl.toFixed(4)} mg/m^3`);
  console.log(`Northern Java Chl-a: ${northChl.toFixed(4)} mg/m^3`);

  if (southChl > northChl) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

